// Downloadable PDFs of the Lernzettel (pdf/*.pdf, generated by scripts/build-pdfs.mjs from print.html).
// Pure functions, no DOM access.

import { AREAS } from './config.js';

export const PDF_DIR = './pdf/';
export const PDF_ALL = 'alle';
export const PDF_GLOSSARY = 'abkuerzungen';

/** File name for an area name, PDF_ALL or PDF_GLOSSARY; null if unknown. */
export function pdfFileName(key) {
  if (key === PDF_ALL) return 'lernzettel-alle.pdf';
  if (key === PDF_GLOSSARY) return 'abkuerzungen.pdf';
  const area = AREAS.find((a) => a.name === key);
  return area ? `lernzettel-${area.id}.pdf` : null;
}

/** All PDFs in display order: all notes, one per area, the glossary. */
export function pdfList() {
  return [
    { key: PDF_ALL, label: 'Alle Lernzettel', file: pdfFileName(PDF_ALL) },
    ...AREAS.map((a) => ({ key: a.name, label: a.name, file: pdfFileName(a.name) })),
    { key: PDF_GLOSSARY, label: 'Abkürzungsverzeichnis', file: pdfFileName(PDF_GLOSSARY) },
  ];
}

/** Notes of one area (or all), in area order and then by title – the order of the PDF. */
export function notesForPdf(catalog, key) {
  const topicsById = new Map(catalog.topics.map((t) => [t.id, t]));
  const areaIndex = new Map(AREAS.map((a, i) => [a.name, i]));
  return (catalog.notes ?? [])
    .filter((n) => topicsById.has(n.topic) && (key === PDF_ALL || topicsById.get(n.topic).area === key))
    .sort((a, b) => {
      const ta = topicsById.get(a.topic);
      const tb = topicsById.get(b.topic);
      return (areaIndex.get(ta.area) ?? 99) - (areaIndex.get(tb.area) ?? 99) || a.title.localeCompare(b.title, 'de');
    });
}

/** "1,2 MB" / "850 KB" for a byte count (German number format). */
export function formatFileSize(bytes) {
  if (!(bytes >= 0)) return '';
  if (bytes < 1000 * 1000) return `${Math.max(1, Math.round(bytes / 1000))} KB`;
  return `${(bytes / 1000 / 1000).toFixed(1).replace('.', ',')} MB`;
}
